import { ApiLog } from "@/types/api";
import { API_BASE_URL } from "@/config/env";

export const logsApi = {
  async getAll(): Promise<ApiLog[]> {
    try {
      const response = await fetch(`${API_BASE_URL}/logs_list`);
      
      if (!response.ok) {
        if (response.status === 404) {
          return [];
        }
        throw new Error(`Failed to fetch logs: ${response.statusText}`);
      }
      
      const data = await response.json();
      
      if (!Array.isArray(data)) {
        throw new Error("Invalid response format: expected array");
      }
      
      return data;
    } catch (error) {
      if (error instanceof TypeError && error.message.includes('fetch')) {
        throw new Error("Network error: Unable to connect to server");
      }
      throw error;
    }
  },

  async getById(logId: number): Promise<ApiLog> {
    try {
      const response = await fetch(`${API_BASE_URL}/logs/${logId}`);
      
      if (!response.ok) {
        if (response.status === 404) {
          throw new Error(`Log with ID ${logId} not found`);
        }
        throw new Error(`Failed to fetch log ${logId}: ${response.statusText}`);
      }
      
      return response.json();
    } catch (error) {
      if (error instanceof TypeError && error.message.includes('fetch')) {
        throw new Error("Network error: Unable to connect to server");
      }
      throw error;
    }
  },

  async delete(logId: number): Promise<void> {
    try {
      const response = await fetch(`${API_BASE_URL}/logs/${logId}`, {
        method: "DELETE"
      });
      
      if (!response.ok) {
        if (response.status === 404) {
          throw new Error(`Log with ID ${logId} not found`);
        }
        throw new Error(`Failed to delete log ${logId}: ${response.statusText}`);
      }
    } catch (error) {
      if (error instanceof TypeError && error.message.includes('fetch')) {
        throw new Error("Network error: Unable to connect to server");
      }
      throw error;
    }
  },

  async deleteMultiple(logIds: number[]): Promise<void> {
    if (logIds.length === 0) {
      return;
    }
    
    const results = await Promise.allSettled(
      logIds.map(id => this.delete(id))
    );
    
    const failures = results.filter(result => result.status === 'rejected');
    if (failures.length > 0) {
      const failedIds = failures.map((_, index) => logIds[index]).join(', ');
      throw new Error(`Failed to delete logs: ${failedIds}`);
    }
  }
}; 