import { InputMapping, OutputMapping } from "@/types/mapping";

interface ReadOnlyMappingsTableProps {
  type: "input" | "output";
  mappings: (InputMapping | OutputMapping)[];
}

export function ReadOnlyMappingsTable({ type, mappings }: ReadOnlyMappingsTableProps) {
  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="bg-gray-700 text-white">
              <th className="px-4 py-2 text-center text-xs font-semibold border-r border-gray-600">
                {type === "input" ? "Column" : "Name"}
              </th>
              {type === "input" && (
                <>
                  <th className="px-4 py-2 text-center text-xs font-semibold border-r border-gray-600">Source</th>
                  <th className="px-4 py-2 text-center text-xs font-semibold border-r border-gray-600">Forced Value</th>
                </>
              )}
              <th className="px-4 py-2 text-center text-xs font-semibold">Cell</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {mappings.map((mapping) => {
              const isInputMapping = type === "input" && "source" in mapping;
              
              return (
                <tr key={mapping.id} className="hover:bg-gray-50">
                  <td className="px-4 py-2 text-center border-r border-gray-200 text-xs">
                    {type === "input" ? (mapping as InputMapping).column : (mapping as OutputMapping).name}
                  </td>
                  {isInputMapping && (
                    <>
                      <td className="px-4 py-2 text-center border-r border-gray-200 text-xs">
                        <span className={`px-2 py-1 rounded text-xs font-medium ${
                          (mapping as InputMapping).source === "forced_input" 
                            ? "bg-orange-100 text-orange-800" 
                            : "bg-blue-100 text-blue-800"
                        }`}>
                          {(mapping as InputMapping).source === "forced_input" ? "Forced" : "Input File"}
                        </span>
                      </td>
                      <td className="px-4 py-2 text-center border-r border-gray-200 text-xs">
                        {(mapping as InputMapping).forcedValue || <span className="text-gray-400">—</span>}
                      </td>
                    </>
                  )}
                  <td className="px-4 py-2 text-center text-xs font-mono">
                    {mapping.cell}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
} 