import { useState, useEffect, useRef } from "react";
import { useTemplatesStore } from "@/store/templates";
import { useNavigation } from "@/hooks/useNavigation";
import { processExcel } from "@/services/batchApi";
import { toast } from "react-toastify";
import { getTemplates, getTemplateById } from "@/services/templateApi";
import { Template } from "@/types/mapping";
import { parseCsvFile } from "@/services/csvService";

export const useTemplateForm = () => {
  // State
  const [selectedId, setSelectedId] = useState<string>("");
  const [selectedTemplate, setSelectedTemplate] = useState<Template | null>(null);
  const [forcedValues, setForcedValues] = useState<Record<string, string>>({});
  const [csvPreview, setCsvPreview] = useState<string[][]>([]);
  const [csvFile, setCsvFile] = useState<File | null>(null);
  const [excelFile, setExcelFile] = useState<File | null>(null);
  const [outputUrl, setOutputUrl] = useState<string>("");
  const [resultCsv, setResultCsv] = useState<string>("");
  const [resultJson, setResultJson] = useState<Record<string, string>[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [errors, setErrors] = useState<string[]>([]);
  const [skipRows, setSkipRows] = useState<boolean>(false);
  
  // Refs
  const initializedRef = useRef(false);
  
  // Store
  const { loadTemplates, selectedTemplateId } = useTemplatesStore();
  const { params } = useNavigation();

  // Load templates and initialize selection
  useEffect(() => {
    const fetchTemplates = async () => {
      try {
        const fetchedTemplates = await getTemplates();
        await loadTemplates(fetchedTemplates);
        
        if (!initializedRef.current) {
          initializedRef.current = true;
          
          const templateToSelect = selectedTemplateId || params.template;
          
          if (templateToSelect) {
            setTimeout(() => {
              setSelectedId(templateToSelect);
            }, 100);
          }
        }
      } catch {
        toast.error("Error loading templates");
      }
    };
    
    fetchTemplates();
  }, [loadTemplates, params.template, selectedTemplateId]);

  // Set selected template ID from store or URL params
  useEffect(() => {
    if ((selectedTemplateId || params.template) && !selectedId) {
      const templateId = selectedTemplateId || params.template;
      if (templateId) {
        setSelectedId(templateId);
      }
    }
  }, [params.template, selectedTemplateId, selectedId]);

  // Load template details when selectedId changes
  useEffect(() => {
    const fetchTemplateDetails = async () => {
      if (!selectedId) return;
      
      try {
        setIsLoading(true);
        const templateDetails = await getTemplateById(selectedId);
        
        setSelectedTemplate(templateDetails);
        
        // Initialize values for forced inputs
        initializeForcedValues(templateDetails);
      } catch {
        toast.error("Error loading template details");
      } finally {
        setIsLoading(false);
      }
    };
    
    fetchTemplateDetails();
  }, [selectedId]);

  // Initialize forced values from template
  const initializeForcedValues = (template: Template) => {
    const initialValues: Record<string, string> = {};
    
    template.inputMappings
      .filter(mapping => mapping.source === "forced_input")
      .forEach(mapping => {
        initialValues[mapping.id] = mapping.forcedValue || "";
      });
    
    setForcedValues(initialValues);
  };

  // Handle forced input change
  const handleForcedInput = (key: string, value: string) => {
    const sanitizedValue = value.replace(/\s+/g, '');
    setForcedValues((prev) => ({ ...prev, [key]: sanitizedValue }));
  };

  // Handle CSV file selection
  const handleCsvChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || !files[0]) return;
    
    const file = files[0];
    setCsvFile(file);
    
    try {
      const parsedData = await parseCsvFile(file);
      setCsvPreview(parsedData.slice(0, 5));
    } catch {
      setErrors(["Failed to parse CSV file"]);
    }
  };

  // Handle Excel file selection
  const handleExcelChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || !files[0]) return;
    
    const file = files[0];
    
    if (!file.name.endsWith('.xlsx') && !file.name.endsWith('.xls')) {
      setErrors(['Please select an Excel file (.xlsx or .xls)']);
      return;
    }
    
    if (file.size === 0) {
      setErrors(['File is empty. Please select a valid Excel file.']);
      return;
    }
    
    setExcelFile(file);
  };

  // Process the Excel or CSV file with selected template
  const handleRun = async () => {
    if (!selectedTemplate) return { success: false };

    setIsLoading(true);
    setErrors([]);

    try {
      const fileToUse = validateAndGetFile();
      if (!fileToUse) return { success: false };
      
      if (!validateForcedValues()) return { success: false };
      
      const result = await sendForProcessing();
      console.log('Processing result:', result);
      
      if (result.success) {
        if (result.file_url) {
          setOutputUrl(result.file_url);
        }
        
        if (result.csv) {
          console.log('Setting CSV result:', result.csv);
          setResultCsv(result.csv);
        }
        
        if (result.json && Array.isArray(result.json)) {
          console.log('Setting JSON result:', result.json);
          setResultJson(result.json);
        }
        
        // Якщо є помилки при skip_rows=true, все одно показуємо їх як попередження
        if (result.errors && result.errors.length > 0 && skipRows) {
          toast.warn(`Processing completed with warnings: ${result.errors.join('; ')}`);
        }
      } else {
        // Коли skip_rows=false або інші критичні помилки
        handleProcessingError(result.errors);
      }
      
      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      setErrors([errorMessage]);
      return { success: false, errors: [errorMessage] };
    } finally {
      setIsLoading(false);
    }
  };
  
  const validateAndGetFile = (): File | null => {
    const hasInputFileMappings = selectedTemplate?.inputMappings.some(m => m.source === "input_file");
    const allForcedInputs = selectedTemplate?.inputMappings.every(m => m.source === "forced_input");
    
    if (allForcedInputs) {
      if (excelFile) {
        return excelFile;
      }
      setErrors(["Please select an Excel file for processing"]);
      setIsLoading(false);
      return null;
    }
    
    if (hasInputFileMappings) {
      if (csvFile) {
        return csvFile;
      }
      if (excelFile) {
        return excelFile;
      }
      setErrors(["Please select an Excel or CSV file for processing"]);
      setIsLoading(false);
      return null;
    }
    
    setErrors(["No input mappings found in template"]);
    setIsLoading(false);
    return null;
  };
  
  const validateForcedValues = (): boolean => {
    if (!selectedTemplate) return false;
    
    const forcedInputErrors: string[] = [];
    
    selectedTemplate.inputMappings.forEach(mapping => {
      if (mapping.source === "forced_input") {
        const value = forcedValues[mapping.id];
        if (!value) {
          forcedInputErrors.push(`Value for "${mapping.column}" is required`);
        }
      }
    });
    
    if (forcedInputErrors.length > 0) {
      setErrors(forcedInputErrors);
      setIsLoading(false);
      return false;
    }
    
    return true;
  };
  
  const sendForProcessing = async () => {
    return await processExcel({
      templateId: selectedId,
      excelData: [],
      forcedValues: forcedValues,
      excel_file: excelFile,
      csv_file: csvFile,
      skip_rows: skipRows
    });
  };
  
  const handleProcessingError = (resultErrors?: string[]): void => {
    if (resultErrors && resultErrors.length > 0) {
      setErrors(resultErrors);
      
      // Показуємо toast з першою помилкою для швидкого сповіщення
      const firstError = resultErrors[0];
      if (!skipRows) {
        toast.error(`Processing halted: ${firstError}`);
      } else {
        toast.error(`Processing failed: ${firstError}`);
      }
    } else {
      setErrors(["File processing error"]);
      toast.error("Unknown file processing error occurred");
    }
  };

  // Function to update template data
  const refreshTemplate = async () => {
    if (!selectedId) return;
    
    try {
      setIsLoading(true);
      const templateDetails = await getTemplateById(selectedId);
      setSelectedTemplate(templateDetails);
      
      // Update forced input values
      initializeForcedValues(templateDetails);
    } catch {
      toast.error("Error refreshing template data");
    } finally {
      setIsLoading(false);
    }
  };

  return {
    selectedId,
    setSelectedId,
    selectedTemplate,
    forcedValues,
    csvPreview,
    csvFile,
    excelFile,
    outputUrl,
    resultCsv,
    resultJson,
    isLoading,
    errors,
    skipRows,
    setSkipRows,
    handleForcedInput,
    handleCsvChange,
    handleExcelChange,
    handleRun,
    refreshTemplate
  };
}; 