import { useState } from "react"
import { Button } from "@/components/ui/buttons"
import { RadioGroup, RadioGroupItem } from "@/components/ui/forms"
import { useNavigation } from "@/hooks/useNavigation"
import { useTemplatesStore } from "@/store/templates"
import { useEffect } from "react"
import { toast } from "react-toastify"
import { RunMode, DEFAULT_RUN_MODE, Page, Mode } from "@/constants/navigation"
import { TemplateSelector } from "@/components/templates/TemplateSelector"

export const RunModal = () => {
  const [mode, setMode] = useState<RunMode>(DEFAULT_RUN_MODE)
  const [template, setTemplate] = useState<string>("")
  const { navigateTo } = useNavigation()
  const { loadTemplates, setSelectedTemplate } = useTemplatesStore()
  
  useEffect(() => {
    loadTemplates()
  }, [loadTemplates])

  const handleOk = () => {
    if (mode === RunMode.NEW) {
      navigateTo(Page.TEMPLATE, Mode.CREATE)
      return
    }

    if (!template) {
      toast.error("Please select a template")
      return
    }

    setSelectedTemplate(template)
    
    navigateTo(Page.RUN_TEMPLATE, undefined, { template })
  }

  const handleModeChange = (value: string) => {
    setMode(value as RunMode)
  }

  return (
    <div className="flex items-center justify-center h-full min-h-[calc(100vh-100px)]">
      <div className="bg-white max-w-md rounded-2xl shadow-2xl p-6 px-4 border border-gray-200">
        <div className="mb-4">
          <h2 className="text-xl font-semibold mb-2">Run batch</h2>
        </div>
        <div className="flex gap-8 mb-6">
          <RadioGroup value={mode} onValueChange={handleModeChange} className="flex justify-between w-full">
            <div className="flex items-center gap-2">
              <RadioGroupItem value={RunMode.NEW} id={RunMode.NEW} className="w-5 h-5 border-2 border-gray-400 rounded-full data-[state=checked]:border-green-600 data-[state=checked]:bg-green-600 focus:ring-2 focus:ring-green-200" />
              <label htmlFor={RunMode.NEW} className="text-base select-none">Create new</label>
            </div>
            <div className="flex items-center gap-2">
              <RadioGroupItem value={RunMode.TEMPLATE} id={RunMode.TEMPLATE} className="w-5 h-5 border-2 border-gray-400 rounded-full data-[state=checked]:border-green-600 data-[state=checked]:bg-green-600 focus:ring-2 focus:ring-green-200" />
              <label htmlFor={RunMode.TEMPLATE} className="text-base select-none">Use template</label>
            </div>
          </RadioGroup>
        </div>
        {mode === RunMode.TEMPLATE && (
          <div className="mb-6">
            <TemplateSelector
              selectedId={template}
              setSelectedId={setTemplate}
              showDescription={true}
            />
          </div>
        )}
        <div className="flex justify-center mt-4">
          <Button variant="excel" className="w-full" onClick={handleOk}>OK</Button>
        </div>
      </div>
    </div>
  )
} 