/* global Office */

Office.onReady((info) => {
  if (info.host === Office.HostType.Excel) {
    // Excel is ready
  }
});

export const getSelectedRange = async () => {
  const range = await Excel.run(async (context) => {
    const range = context.workbook.getSelectedRange();
    range.load('address');
    await context.sync();
    return range;
  });
  return range;
};

export const writeToRange = async (value: string) => {
  await Excel.run(async (context) => {
    const range = context.workbook.getSelectedRange();
    range.values = [[value]];
    await context.sync();
  });
};

export const getActiveWorksheetData = async (): Promise<string[][]> => {
  return await Excel.run(async (context) => {
    const worksheet = context.workbook.worksheets.getActiveWorksheet();
    worksheet.load(['name', 'position']);
    
    const usedRange = worksheet.getUsedRange();
    usedRange.load(['values', 'address', 'rowCount', 'columnCount']);
    
    await context.sync();
    
    const values = usedRange.values;
    
    if (!values || values.length === 0 || values[0].length === 0) {
      return [["No data found in active worksheet"]];
    }
    
    return values;
  });
};

export const exportActiveWorkbookAsFile = async (): Promise<File> => {
  return new Promise((resolve, reject) => {
    try {
      if (!Office || !Office.context || !Office.context.document) {
        reject(new Error("Office API is not available"));
        return;
      }
      Office.context.document.getFileAsync(
        Office.FileType.Compressed, 
        { sliceSize: 65536 },
        (result) => {
          if (result.status === Office.AsyncResultStatus.Succeeded) {
            const officeFile = result.value;
            if (!officeFile || officeFile.sliceCount === 0) {
              if (officeFile && typeof officeFile.closeAsync === 'function') {
                officeFile.closeAsync();
              }
              reject(new Error("Excel file is empty (no slices)"));
              return;
            }
            const fileData: Uint8Array[] = [];
            const getSlice = (sliceIndex: number, totalSlices: number) => {
              officeFile.getSliceAsync(sliceIndex, (sliceResult) => {
                if (sliceResult.status === Office.AsyncResultStatus.Succeeded) {
                  const data = new Uint8Array(sliceResult.value.data);
                  fileData.push(data);
                  if (sliceIndex === totalSlices - 1) {
                    let totalLength = 0;
                    fileData.forEach((chunk) => {
                      totalLength += chunk.length;
                    });
                    if (totalLength === 0) {
                      officeFile.closeAsync();
                      reject(new Error("Excel file data is empty"));
                      return;
                    }
                    const combinedArray = new Uint8Array(totalLength);
                    let offset = 0;
                    fileData.forEach((chunk) => {
                      combinedArray.set(chunk, offset);
                      offset += chunk.length;
                    });
                    const mimeType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
                    const excelFile = new File(
                      [combinedArray],
                      "active_workbook.xlsx",
                      { 
                        type: mimeType,
                        lastModified: Date.now()
                      }
                    );
                    if (excelFile.size === 0) {
                      officeFile.closeAsync();
                      reject(new Error("Created Excel file has zero size"));
                      return;
                    }
                    officeFile.closeAsync();
                    resolve(excelFile);
                  } else {
                    getSlice(sliceIndex + 1, totalSlices);
                  }
                } else {
                  officeFile.closeAsync();
                  reject(new Error(`Error getting slice: ${sliceResult.error.message}`));
                }
              });
            };
            getSlice(0, officeFile.sliceCount);
          } else {
            reject(new Error(`Error getting file: ${result.error.message}`));
          }
        }
      );
    } catch (error) {
      reject(error);
    }
  });
};

export const writeCsvToWorksheet = async (csvData: string): Promise<void> => {
  if (!csvData || csvData.trim() === '') {
    throw new Error('No CSV data provided');
  }
  if (typeof Excel === 'undefined') {
    throw new Error('Excel API is not available. Make sure you are running in Excel.');
  }
  await Excel.run(async (context) => {
    const worksheetName = "Processed Data";
    let worksheet;
    const workbook = context.workbook;
    workbook.load(['name']);
    await context.sync();
    try {
      worksheet = context.workbook.worksheets.getItem(worksheetName);
      worksheet.load(['name', 'position']);
      await context.sync();
      const usedRange = worksheet.getUsedRange();
      usedRange.load(['address']);
      await context.sync();
      usedRange.clear();
    } catch {
      worksheet = context.workbook.worksheets.add();
      worksheet.name = worksheetName;
      await context.sync();
    }
    const lines = csvData.split('\n').filter(line => line.trim() !== '');
    if (lines.length < 2) {
      throw new Error('CSV must contain at least a header and one data row');
    }
    const headers = lines[0].split(',').map(h => h.trim());
    const headerRange = worksheet.getRange(`A1:${String.fromCharCode(65 + headers.length - 1)}1`);
    headerRange.values = [headers];
    await context.sync();
    const dataOnlyValues = lines.slice(1).map(line => 
      line.split(',').map(v => {
        const trimmed = v.trim();
        if (trimmed === '#VALUE!') return '';
        const num = Number(trimmed);
        return isNaN(num) ? trimmed : num;
      })
    );
    headerRange.format.font.bold = true;
    headerRange.format.fill.color = "#e6e8ef";
    headerRange.format.font.size = 12;
    headerRange.format.borders.getItem('EdgeBottom').style = 'Continuous';
    headerRange.format.borders.getItem('EdgeBottom').weight = 'Medium';
    await context.sync();
    worksheet.freezePanes.freezeRows(1);
    await context.sync();
    if (dataOnlyValues.length > 0) {
      const dataRange = worksheet.getRange(
        `A2:${String.fromCharCode(65 + headers.length - 1)}${lines.length}`
      );
      dataRange.values = dataOnlyValues;
      await context.sync();
      const fullRange = worksheet.getRange(
        `A1:${String.fromCharCode(65 + headers.length - 1)}${lines.length}`
      );
      fullRange.format.borders.getItem("EdgeLeft").style = "Continuous";
      fullRange.format.borders.getItem("EdgeRight").style = "Continuous";
      fullRange.format.borders.getItem("EdgeTop").style = "Continuous";
      fullRange.format.borders.getItem("EdgeBottom").style = "Continuous";
      fullRange.format.borders.getItem("InsideVertical").style = "Continuous";
      fullRange.format.borders.getItem("InsideHorizontal").style = "Continuous";
      fullRange.format.horizontalAlignment = "Left";
      await context.sync();
      fullRange.format.autofitColumns();
      await context.sync();
    }
    worksheet.activate();
    await context.sync();
    const a1Cell = worksheet.getRange("A1");
    a1Cell.select();
    await context.sync();
    context.sync().then(() => {
      const intervalTimes = 5;
      let counter = 0;
      const setHeaderInterval = setInterval(() => {
        try {
          Excel.run(async (innerContext) => {
            const innerWorksheet = innerContext.workbook.worksheets.getItem("Processed Data");
            const innerHeadersRange = innerWorksheet.getRange("A1");
            innerHeadersRange.values = [[headers[0]]];
            innerHeadersRange.format.font.bold = true;
            innerHeadersRange.format.fill.color = "#e6e8ef";
            innerHeadersRange.select();
            await innerContext.sync();
          }).catch(() => {});
          counter++;
          if (counter >= intervalTimes) {
            clearInterval(setHeaderInterval);
          }
        } catch {
          clearInterval(setHeaderInterval);
        }
      }, 300);
    });
    Excel.run(async (ctx) => {
      const ws = ctx.workbook.worksheets.getItem("Processed Data");
      ws.names.add("HeaderCell", ws.getRange("A1"));
      await ctx.sync();
    }).catch(() => {});
    await context.sync();
  });
}; 