import { Template, InputMapping, OutputMapping } from "@/types/mapping";
import { apiGet, apiPost, apiDelete, apiPut } from "./api";
import type { 
  CreateTemplateData, 
  UpdateTemplateData, 
  ApiTemplate, 
  ApiTemplateDetail 
} from "@/types/api";

export const getTemplates = async (): Promise<Template[]> => {
  try {
    const response = await apiGet<ApiTemplate[]>("/templates_list");
    
    if (response.error) {
      // If server says no templates found, return empty array instead of error
      if (response.error.toLowerCase().includes("no template") || 
          response.error.toLowerCase().includes("not found")) {
        return [];
      }
      throw new Error(`Failed to get templates: ${response.error}`);
    }
    
    if (response.data === undefined || response.data === null) {
      throw new Error("Server returned no data");
    }

    if (!Array.isArray(response.data)) {
      throw new Error("Server returned invalid data format");
    }
    
    // If empty array, return empty array - this is not an error
    if (response.data.length === 0) {
      return [];
    }
    
    // Get full template data for each template
    const templates = await Promise.all(
      response.data.map(async (template) => {
        const fullTemplate = await getTemplateById(template.id.toString());
        return fullTemplate;
      })
    );
    
    return templates;
  } catch (error) {
    // Don't wrap the error message again if it already contains "Failed to get template"
    const errorMessage = (error as Error).message;
    if (errorMessage.includes("Failed to get template")) {
      throw error;
    }
    throw new Error(`Failed to get templates: ${errorMessage}`);
  }
};

export const getTemplateById = async (templateId: string): Promise<Template> => {
  try {
    const response = await apiGet<ApiTemplateDetail>(`/templates/${templateId}`);
    
    if (response.error) {
      throw new Error(`Failed to get template: ${response.error}`);
    }
    
    if (!response.data) {
      throw new Error("Server returned no data");
    }
    
    const apiTemplate = response.data;
    
    const transformedTemplate = {
      id: apiTemplate.id.toString(),
      name: apiTemplate.name,
      description: apiTemplate.description,
      inputMappings: apiTemplate.input_mappings.map(mapping => {
        const isForcedByType = mapping.source && 
                              mapping.source.toLowerCase().includes('forced');
        const hasForcedValue = mapping.forced_value && mapping.forced_value.trim() !== '';
        
        const isForcedInput = isForcedByType || hasForcedValue;
        
        return {
          id: `${mapping.name}_${mapping.cell}`,
          column: mapping.name,
          cell: mapping.cell,
          source: isForcedInput ? "forced_input" : "input_file",
          forcedValue: mapping.forced_value
        };
      }) as InputMapping[],
      outputMappings: apiTemplate.output_mappings.map(mapping => ({
        id: `${mapping.field}_${mapping.cell}`,
        name: mapping.field,
        cell: mapping.cell
      })) as OutputMapping[],
      identityMappings: (apiTemplate.identity_mappings || [])
        .map(mapping => ({
          id: mapping.id?.toString() ?? "",
          templateId: mapping.template_id?.toString() ?? "",
          name: mapping.name ?? ""
        })),
      createdAt: new Date().toISOString(),
      selectedMappingIds: (apiTemplate.identity_mappings || [])
        .map(identityMapping => {
          // Find the corresponding input mapping by name and create the same ID format
          const inputMapping = apiTemplate.input_mappings.find(im => im.name === identityMapping.name);
          return inputMapping ? `${inputMapping.name}_${inputMapping.cell}` : '';
        })
        .filter(id => id !== '')
    };
    
    return transformedTemplate;
  } catch (error) {
    throw new Error(`Failed to get template: ${(error as Error).message}`);
  }
};

export const createTemplate = async (template: Omit<Template, "id" | "createdAt">): Promise<ApiTemplate> => {
  try {
    const selectedMappingIds = template.inputMappings.map(m => m.id);
    
    const apiData: CreateTemplateData = {
      name: template.name,
      description: template.description || "",
      input_mappings: template.inputMappings.map(mapping => ({
        name: mapping.column,
        source: "Excel table",
        cell: mapping.cell,
        ...(mapping.forcedValue ? { forced_value: mapping.forcedValue } : {})
      })),
      output_mappings: template.outputMappings.map(mapping => ({
        field: mapping.name,
        cell: mapping.cell
      })),
      identity_mappings: selectedMappingIds.map(id => {
        const mapping = template.inputMappings.find(m => m.id === id);
        return { name: mapping?.column || "" };
      })
    };

    const response = await apiPost<ApiTemplate>("/templates", apiData);
    
    if (response.error) {
      throw new Error(`Failed to create template: ${response.error}`);
    }
    
    if (!response.data) {
      throw new Error("Server returned no data");
    }
    
    return response.data;
  } catch (error) {
    throw new Error(`Template creation failed: ${(error as Error).message}`);
  }
};

export const deleteTemplate = async (templateId: string): Promise<void> => {
  try {
    const response = await apiDelete(`/templates/${templateId}`);
    
    if (response.error) {
      throw new Error(`Failed to delete template: ${response.error}`);
    }
  } catch (error) {
    throw new Error(`Template deletion failed: ${(error as Error).message}`);
  }
};

export const updateTemplate = async (templateId: string, data: UpdateTemplateData): Promise<void> => {
  try {
    const response = await apiPut(`/templates/${templateId}`, data);
    
    if (response.error) {
      throw new Error(`Failed to update template: ${response.error}`);
    }
    
    return;
  } catch (error) {
    throw new Error(`Template update failed: ${(error as Error).message}`);
  }
}; 