import { apiPost } from "./api";

interface ProcessExcelParams {
  templateId: string;
  excelData: string[][];
  forcedValues: Record<string, string>;
  excel_file?: File | null;
  csv_file?: File | null;
  skip_rows?: boolean;
}

interface ProcessContentData {
  json?: Record<string, string>[];
  csv?: string;
}

interface ProcessExcelResponse {
  success: boolean;
  file_url?: string;
  content?: string | ProcessContentData;
  errors?: string[];
  json?: Record<string, string>[];
  csv?: string;
}

export const processExcel = async (data: ProcessExcelParams): Promise<ProcessExcelResponse & ProcessContentData> => {
  try {
    const endpoint = buildEndpointUrl(data.templateId, data.skip_rows);
    const formData = prepareFormData(data.excel_file, data.csv_file);
    const response = await apiPost<ProcessExcelResponse>(endpoint, formData, true);
    
    if (response.error) {
      return handleApiError(response.error);
    }
    
    if (!response.data) {
      return {
        success: false,
        errors: ['No data received from server'],
      };
    }
    
    const result = response.data;
    
    if (result.content && typeof result.content === 'string') {
      try {
        const parsedContent = JSON.parse(result.content) as ProcessContentData;
        
        return {
          ...result,
          success: true,
          json: parsedContent.json,
          csv: parsedContent.csv
        };
      } catch {
        // Ignore parsing errors
      }
    } 
    else if (result.content && typeof result.content === 'object') {
      return {
        ...result,
        success: true,
        json: (result.content as ProcessContentData).json,
        csv: (result.content as ProcessContentData).csv
      };
    }
    else if (result.json || result.csv) {
      return {
        ...result,
        success: true,
        json: result.json,
        csv: result.csv
      };
    }
    else {
      const responseStr = JSON.stringify(response);
      try {
        const parsedResponse = JSON.parse(responseStr);
        
        const findJsonAndCsv = (obj: Record<string, unknown>): { json?: Record<string, string>[], csv?: string } => {
          if (!obj || typeof obj !== 'object') return {};
          
          if (Array.isArray(obj) && obj.length > 0 && typeof obj[0] === 'object') {
            return { json: obj as Record<string, string>[] };
          }
          
          if (obj.json && Array.isArray(obj.json)) {
            return { json: obj.json as Record<string, string>[] };
          }
          
          if (obj.csv && typeof obj.csv === 'string') {
            return { csv: obj.csv };
          }
          
          for (const key in obj) {
            if (typeof obj[key] === 'object' && obj[key] !== null) {
              const found = findJsonAndCsv(obj[key] as Record<string, unknown>);
              if (found.json || found.csv) {
                return found;
              }
            }
          }
          
          return {};
        };
        
        const found = findJsonAndCsv(parsedResponse);
        
        if (found.json || found.csv) {
          return {
            ...result,
            success: true,
            ...found
          };
        }
      } catch {
        // Ignore parsing errors
      }
    }
    
    return {
      ...result,
      success: false,
      errors: ['No valid data found in response']
    };
  } catch {
    return {
      success: false,
      errors: ['Unknown error occurred'],
    };
  }
};

// Build the API endpoint URL with template ID and forced values
const buildEndpointUrl = (templateId: string, skipRows?: boolean): string => {
  const skipParam = skipRows !== undefined ? `&skip_rows=${skipRows}` : '';
  return `/process_excel/?template_id=${templateId}${skipParam}`;
};

// Prepare FormData with file and validation fields
const prepareFormData = (excelFile: File | null | undefined, csvFile: File | null | undefined): FormData => {
  const formData = new FormData();
  
  if (csvFile) {
    formData.append('csv_file', csvFile);
  }
  
  if (excelFile) {
    formData.append('excel_file', excelFile);
  }
  
  return formData;
};

// Handle API error responses
const handleApiError = (error: string): ProcessExcelResponse & ProcessContentData => {
  let userFriendlyError: string;
  
  if (error.includes("body.excel_file")) {
    userFriendlyError = "Error with Excel file: failed to send or incorrect format";
  } else if (error.includes("template_id")) {
    userFriendlyError = "Template error: selected template is unavailable or doesn't exist";
  } else if (error.includes("Validation Error")) {
    try {
      const validationPart = error.replace("Validation Error: ", "");
      const validationErrors = JSON.parse(validationPart);
      
      userFriendlyError = "Data validation error: " + 
        validationErrors.map((err: { loc: string[], msg: string }) => 
          `"${err.loc.join('.')}" - ${err.msg}`
        ).join("; ");
    } catch {
      userFriendlyError = "Data validation error on server";
    }
  } else {
    userFriendlyError = "Error processing request: " + error;
  }
  
  return {
    success: false,
    errors: [userFriendlyError],
  };
};