export interface ValidationRule {
  validate: () => boolean;
  error: string;
  setError: () => void;
}

export interface ValidationResult {
  key: string;
  isValid: boolean;
  setError: () => void;
}

export const createValidationRule = (
  validate: () => boolean,
  error: string,
  setError: () => void
): ValidationRule => ({
  validate,
  error,
  setError,
});

export const validateRules = (rules: Record<string, ValidationRule>): boolean => {
  const invalidRules = Object.entries(rules)
    .map(([key, rule]) => ({ key, isValid: rule.validate(), setError: rule.setError }))
    .filter(result => !result.isValid);
  
  if (invalidRules.length > 0) {
    invalidRules.forEach(rule => rule.setError());
    return false;
  }
  return true;
}; 