import { Input } from "@/components/ui/forms";
import { Template, InputMapping } from "@/types/mapping";
import { useState } from "react";
import { Pencil, Check, X } from "lucide-react";
import { Button } from "@/components/ui/buttons/button";
import { updateTemplate } from "@/services/templateApi";
import { toast } from "react-toastify";
import { ApiInputMapping } from "@/types/api";

interface InputMappingsProps {
  selectedTemplate: Template | null;
  forcedValues: Record<string, string>;
  handleForcedInput: (key: string, value: string) => void;
  refreshTemplate: () => Promise<void>;
}

export const InputMappings = ({ 
  selectedTemplate, 
  forcedValues,
  handleForcedInput,
  refreshTemplate
}: InputMappingsProps) => {
  const [editingInput, setEditingInput] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [editValue, setEditValue] = useState<string>("");

  if (!selectedTemplate || !selectedTemplate.inputMappings) return null;
  
  const startEditing = (input: InputMapping) => {
    setEditingInput(input.id);
    setEditValue(forcedValues[input.id] || input.forcedValue || "");
  };

  const cancelEditing = () => {
    setEditingInput(null);
    setEditValue("");
  };

  const saveInputValue = async (input: InputMapping) => {
    if (!selectedTemplate) return;
    
    try {
      setIsSubmitting(true);
      
      // Create input_mappings array for API request
      const updatedMappings: ApiInputMapping[] = selectedTemplate.inputMappings.map(mapping => {
        if (mapping.id === input.id) {
          return {
            name: mapping.column,
            cell: mapping.cell,
            source: "forced_input",
            forced_value: editValue
          };
        }
        
        return {
          name: mapping.column,
          cell: mapping.cell,
          source: mapping.source === "forced_input" ? "forced_input" : "input_file",
          forced_value: mapping.forcedValue
        };
      });
      
      // Send to backend
      await updateTemplate(selectedTemplate.id, {
        input_mappings: updatedMappings
      });
      
      // Update data in UI through parent component's update function
      handleForcedInput(input.id, editValue);
      
      // Update entire template to get fresh data from backend
      await refreshTemplate();
      
      toast.success("Value updated successfully");
      setEditingInput(null);
    } catch (error) {
      toast.error(`Failed to update: ${(error as Error).message}`);
    } finally {
      setIsSubmitting(false);
    }
  };
  
  return (
    <div className="mb-6">
      <label className="block mb-3 text-base font-semibold">Input Mappings</label>
      <div className="space-y-3 bg-gray-50 p-3 rounded-xl">
        {selectedTemplate.inputMappings.map((input) => (
          <div key={input.id} className="flex items-center gap-2 p-2 bg-white border border-gray-100 rounded-lg">
            <div className="flex-1">
              <div className="font-medium text-green-700">{input.column}</div>
              <div className="text-gray-500 text-xs">{input.cell}</div>
            </div>
            {input.source === "forced_input" ? (
              <div className="flex items-center gap-2">
                {editingInput === input.id ? (
                  <>
                    <Input
                      className="w-32 rounded-xl focus:ring-2 focus:ring-green-200 border-green-600 placeholder:text-gray-400"
                      value={editValue}
                      onChange={(e) => setEditValue(e.target.value.replace(/\s+/g, ''))}
                      onKeyDown={(e) => {
                        if (e.key === " ") {
                          e.preventDefault();
                        } else if (e.key === "Enter") {
                          saveInputValue(input);
                        } else if (e.key === "Escape") {
                          cancelEditing();
                        }
                      }}
                      placeholder="Value"
                      autoFocus
                    />
                    <div className="flex gap-1">
                      <Button
                        onClick={() => saveInputValue(input)}
                        disabled={isSubmitting}
                        size="icon"
                        variant="ghost"
                        className="h-8 w-8 text-green-600 hover:text-green-700 hover:bg-green-50"
                      >
                        <Check className="h-4 w-4" />
                      </Button>
                      <Button
                        onClick={cancelEditing}
                        disabled={isSubmitting}
                        size="icon"
                        variant="ghost"
                        className="h-8 w-8 text-red-600 hover:text-red-700 hover:bg-red-50"
                      >
                        <X className="h-4 w-4" />
                      </Button>
                    </div>
                  </>
                ) : (
                  <>
                    <div className="text-xs text-gray-400 border border-gray-200 rounded-lg px-3 py-2 bg-gray-50">
                      forced value: {input.forcedValue || ""}
                    </div>
                    <Button
                      onClick={() => startEditing(input)}
                      size="icon"
                      variant="ghost"
                      className="h-8 w-8 text-blue-600 hover:text-blue-700 hover:bg-blue-50"
                    >
                      <Pencil className="h-4 w-4" />
                    </Button>
                  </>
                )}
              </div>
            ) : (
              <div className="text-xs text-gray-400 border border-gray-200 rounded-lg px-3 py-2 bg-gray-50">
                {input.forcedValue || input.column}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}; 