import { API_BASE_URL } from "@/config/env";

export const batchActions = {
  openFile: (path: string | null) => {
    if (!path) return;
    const fullUrl = `${API_BASE_URL}${path}`;
    window.open(fullUrl, '_blank');
  },

  rerunFails: (batchId: number) => {
    alert(`Re-run only failed rows of batch ${batchId} (mock only)`);
  },

  viewTemplate: (templateName: string) => {
    alert(`Template: ${templateName}`);
  },

  deleteSelectedRows: (count: number) => {
    alert(`Deleted ${count} records (mock only)`);
  }
};

export const getStatusColor = (status: string) => {
  const colors = {
    Success: "text-green-600 bg-green-50",
    Failed: "text-red-600 bg-red-50", 
    WithErrors: "text-yellow-600 bg-yellow-50",
    Halted: "text-gray-600 bg-gray-50"
  };
  return colors[status as keyof typeof colors] || "text-gray-600 bg-gray-50";
}; 