import { ReactNode } from "react";

interface SortableHeaderProps<T> {
  field: keyof T;
  children: ReactNode;
  currentField: keyof T | null;
  direction: "asc" | "desc";
  onSort: (field: keyof T) => void;
}

export function SortableHeader<T>({ 
  field, 
  children, 
  currentField, 
  direction, 
  onSort 
}: SortableHeaderProps<T>) {
  return (
    <button
      onClick={() => onSort(field)}
      className="flex items-center gap-1 hover:bg-gray-600 px-2 py-1 rounded w-full text-left"
    >
      {children}
      {currentField === field && (
        <span className="text-xs">
          {direction === "asc" ? "↑" : "↓"}
        </span>
      )}
    </button>
  );
} 