import { Template } from "@/types/mapping";

interface OutputMappingsProps {
  selectedTemplate: Template | null;
}

export const OutputMappings = ({ selectedTemplate }: OutputMappingsProps) => {
  if (!selectedTemplate?.outputMappings?.length) return null;
  
  return (
    <div className="mb-6">
      <label className="block mb-3 text-base font-semibold">Output Mappings</label>
      <div className="space-y-3 bg-gray-50 p-3 rounded-xl">
        {selectedTemplate.outputMappings.map((output) => (
          <div key={output.id} className="flex items-center gap-2 p-2 bg-white border border-gray-100 rounded-lg">
            <div className="flex-1">
              <div className="font-medium text-green-700">{output.name}</div>
              <div className="text-gray-500 text-xs">{output.cell}</div>
            </div>
            <div className="text-xs text-blue-500 bg-blue-50 border border-blue-200 rounded-lg px-3 py-2">
              Output
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}; 