interface ErrorDisplayProps {
  errors: string[];
}

export const ErrorDisplay = ({ errors }: ErrorDisplayProps) => {
  if (errors.length === 0) return null;
  
  return (
    <div className="bg-red-50 border border-red-200 text-red-700 p-3 rounded-lg mb-4">
      <div className="font-medium mb-2">Processing Error:</div>
      <ul className="list-disc pl-5 space-y-1 text-sm">
        {errors.map((error, index) => (
          <li key={index}>{error}</li>
        ))}
      </ul>
      
      {errors.some(err => err.includes("body.excel_file") || err.includes("No Excel data available")) && (
        <div className="mt-3 p-2 bg-yellow-50 border border-yellow-200 rounded text-yellow-800 text-xs">
          <p className="font-medium">Excel file issue:</p>
          <ul className="list-disc pl-4 mt-1">
            <li>Make sure you selected the correct file</li>
            <li>File must be in .xlsx or .xls format</li>
            <li>Try selecting a different file</li>
            <li>The file might be corrupted or locked</li>
          </ul>
        </div>
      )}
      
      {errors.some(err => err.includes("template_id")) && (
        <div className="mt-3 p-2 bg-yellow-50 border border-yellow-200 rounded text-yellow-800 text-xs">
          <p className="font-medium">Template issue:</p>
          <ul className="list-disc pl-4 mt-1">
            <li>Make sure you selected a template from the list</li>
            <li>Try selecting a different template</li>
            <li>The selected template might be unavailable or deleted</li>
          </ul>
        </div>
      )}
    </div>
  );
}; 