import { useTemplateForm } from "@/hooks/useTemplateForm";
import { TemplateSelector } from "@/components/templates/TemplateSelector";
import { InputMappings } from "@/components/templates/InputMappings";
import { FileUploaders } from "@/components/templates/FileUploaders";
import { OutputMappings } from "@/components/templates/OutputMappings";
import { IdentityMappings } from "@/components/templates/IdentityMappings";
import { ActionButtons } from "@/components/templates/ActionButtons";
import { ErrorDisplay } from "@/components/templates/ErrorDisplay";
import { ErrorHandlingMode } from "@/components/templates/ErrorHandlingMode";
import { BackButton } from "@/components/ui/buttons/BackButton";


export const UseTemplate = () => {
  const {
    selectedId,
    setSelectedId,
    selectedTemplate,
    forcedValues,
    csvPreview,
    csvFile,
    excelFile,
    outputUrl,
    isLoading,
    errors,
    skipRows,
    setSkipRows,
    handleForcedInput,
    handleCsvChange,
    handleExcelChange,
    handleRun,
    refreshTemplate,
  } = useTemplateForm();

  return (
    <div className="flex items-center justify-center h-full min-h-[calc(100vh-100px)]">
      <div className="bg-white rounded-2xl shadow-2xl p-6 px-4 border w-full max-w-2xl border-gray-200">
        <div className="mb-4 flex justify-between items-center">
          <h2 className="text-xl font-semibold">Use Template</h2>
          <BackButton />
        </div>
        
        <ErrorDisplay errors={errors} />
        
        <TemplateSelector
          selectedId={selectedId}
          setSelectedId={setSelectedId}
          showDescription={true}
        />

        <InputMappings
          selectedTemplate={selectedTemplate}
          forcedValues={forcedValues}
          handleForcedInput={handleForcedInput}
          refreshTemplate={refreshTemplate}
        />

        <IdentityMappings selectedTemplate={selectedTemplate} />

        <FileUploaders
          selectedTemplate={selectedTemplate}
          csvPreview={csvPreview}
          csvFile={csvFile}
          excelFile={excelFile}
          handleCsvChange={handleCsvChange}
          handleExcelChange={handleExcelChange}
        />

        <ErrorHandlingMode
          skipRows={skipRows}
          setSkipRows={setSkipRows}
        />

        <OutputMappings selectedTemplate={selectedTemplate} />

        <ActionButtons
          selectedTemplate={selectedTemplate}
          isLoading={isLoading}
          outputUrl={outputUrl}
          excelFile={excelFile}
          csvFile={csvFile}
          handleRun={handleRun}
        />
      </div>
    </div>
  );
}; 