interface MappingCellProps {
  value: string;
  error?: string;
  onChange: (value: string) => void;
  type: "text" | "select";
  options?: { value: string; label: string }[];
  placeholder?: string;
}

export function MappingCell({ value, onChange, type, options, placeholder }: MappingCellProps) {
  return (
    <div>
      {type === "select" ? (
        <select
          className="h-7 w-full px-2 py-0 border border-gray-200 rounded-md focus:border-gray-400 focus:ring-1 focus:ring-gray-200 bg-white hover:border-gray-300 transition-colors cursor-pointer text-gray-900 text-xs"
          value={value}
          onChange={(e) => onChange(e.target.value)}
        >
          {options?.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      ) : (
        <input
          className="h-7 w-full border border-gray-200 rounded-md focus:border-gray-400 text-center py-0 text-xs"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
        />
      )}
    </div>
  );
} 