import { useState, useEffect, useCallback } from "react";
import { BatchRun } from "@/types/batch";
import { logsApi } from "@/services/logsApi";

export const useBatchRuns = () => {
  const [data, setData] = useState<BatchRun[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isEmpty, setIsEmpty] = useState(false);

  const fetchBatchRuns = useCallback(async () => {
    setLoading(true);
    setError(null);
    setIsEmpty(false);
    
    try {
      const apiLogs = await logsApi.getAll();
      
      if (apiLogs.length === 0) {
        setIsEmpty(true);
        setData([]);
        return;
      }
      
      setData(apiLogs as BatchRun[]);
      setIsEmpty(false);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "Failed to fetch batch runs";
      setError(errorMessage);
      setData([]);
      setIsEmpty(false);
    } finally {
      setLoading(false);
    }
  }, []);

  const deleteBatchRuns = useCallback(async (ids: number[]) => {
    if (ids.length === 0) {
      return;
    }
    
    setLoading(true);
    setError(null);
    
    try {
      await logsApi.deleteMultiple(ids);
      
      setData(prev => {
        const newData = prev.filter(run => !ids.includes(run.id));
        if (newData.length === 0) {
          setIsEmpty(true);
        }
        return newData;
      });
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "Failed to delete batch runs";
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchBatchRuns();
  }, [fetchBatchRuns]);

  return {
    data,
    loading,
    error,
    isEmpty,
    refetch: fetchBatchRuns,
    deleteBatchRuns
  };
}; 