import { Button } from "@/components/ui/buttons";
import { Loader2 } from "lucide-react";
import { writeCsvToWorksheet } from "@/lib/excel/office";
import { toast } from "react-toastify";
import { Template } from "@/types/mapping";
import { DownloadButton } from "./DownloadButton";
import { useState } from "react";

interface ActionButtonsProps {
  selectedTemplate: Template | null;
  isLoading: boolean;
  outputUrl: string;
  excelFile: File | null;
  csvFile: File | null;
  handleRun: () => Promise<{
    success: boolean;
    file_url?: string;
    errors?: string[];
    json?: Record<string, string>[];
    csv?: string;
    dowload_links?: {
      json: string;
      csv: string;
    };
  }>;
}

export const ActionButtons = ({
  selectedTemplate,
  isLoading,
  outputUrl,
  excelFile,
  csvFile,
  handleRun
}: ActionButtonsProps) => {
  const [downloadLinks, setDownloadLinks] = useState<{ json: string; csv: string } | undefined>();

  const writeResultToExcel = async (url?: string) => {
    const fileUrl = url || outputUrl;
    
    if (!fileUrl) {
      toast.error("No data available to write to Excel");
      return;
    }

    try {
      const response = await fetch(fileUrl);
      
      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Failed to fetch data: ${response.status} ${response.statusText}\nBody: ${errorText}`);
      }

      const csvData = await response.text();
      
      if (!csvData || csvData.trim() === '') {
        throw new Error("Received empty data from server");
      }
      
      const lines = csvData.trim().split('\n');
      if (lines.length < 2) {
        throw new Error(`Received incomplete data: ${lines.length} lines`);
      }
      
      const headers = lines[0].split(',');
      if (headers.length === 0) {
        throw new Error("Received CSV data without headers");
      }

      await writeCsvToWorksheet(csvData);
      
      if (typeof Excel !== "undefined") {
        try {
          await Excel.run(async (context) => {
            const sheet = context.workbook.worksheets.getItem("Processed Data");
            sheet.activate();
            
            const headerCell = sheet.getRange("A1");
            headerCell.format.font.bold = true;
            headerCell.select();
            
            await context.sync();
            
            sheet.freezePanes.freezeRows(1);
            await context.sync();
          });
          
          for (let i = 0; i < 3; i++) {
            setTimeout(() => {
              Excel.run(async (context) => {
                try {
                  const sheet = context.workbook.worksheets.getItem("Processed Data");
                  const header = sheet.getRange("A1");
                  header.format.font.bold = true;
                  header.select();
                  await context.sync();
                } catch {
                  // Ignore post-display protection errors
                }
              }).catch(() => {
                // Ignore Excel run errors
              });
            }, 500 * (i + 1));
          }
        } catch {
          // Ignore Excel API errors
        }
      }
      
      // Focus Excel window
      if (Office && Office.context && Office.context.document) {
        setTimeout(() => {
          Office.context.document.setSelectedDataAsync("", {
            coercionType: Office.CoercionType.Text,
            asyncContext: null
          }, (result) => {
            if (result.status === Office.AsyncResultStatus.Succeeded) {
              Office.context.document.goToByIdAsync("Processed Data", Office.GoToType.NamedItem, () => {
                setTimeout(() => {
                  toast.success("Data has been written to Excel", {
                    autoClose: 3000,
                    position: "top-center"
                  });
                }, 1500);
              });
            } else {
              setTimeout(() => {
                toast.success("Data has been written to Excel", {
                  autoClose: 3000,
                  position: "top-center"
                });
              }, 2000);
            }
          });
        }, 700); 
      } 
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
      toast.error(`Failed to write data to Excel: ${errorMessage}`);
    }
  };

  const handleProcessAndDownload = async () => {
    try {
      const result = await handleRun();
      
      if (result && result.success && (result.file_url || (result.json && result.csv))) {
        if (result.dowload_links) {
          setDownloadLinks(result.dowload_links);
        }
        
        try {
          await new Promise(resolve => setTimeout(resolve, 200));
          if (result.file_url) {
            await writeResultToExcel(result.file_url);
          } else if (result.csv) {
            await writeCsvToWorksheet(result.csv);
            toast.success("Data has been written to Excel", {
              autoClose: 3000,
              position: "top-center"
            });
          }
        } catch {
          if (outputUrl) {
            await new Promise(resolve => setTimeout(resolve, 300));
            await writeResultToExcel(outputUrl);
          }
        }
      } else {
        await new Promise(resolve => setTimeout(resolve, 200));
        if (result && result.errors && result.errors.length) {
          toast.error(result.errors[0]);
        } else {
          toast.error("Processing failed to return valid result");
        }
      }
    } catch {
      await new Promise(resolve => setTimeout(resolve, 200));
      toast.error("Failed to process Excel file");
    }
  };

  if (!selectedTemplate) return null;
  
  return (
    <div className="flex flex-col gap-3 mt-6">
      <Button 
        variant="excel"
        className="w-full py-2.5 rounded-xl" 
        onClick={handleProcessAndDownload}
        disabled={isLoading || (!excelFile && !csvFile)}
      >
        {isLoading ? (
          <span className="flex items-center">
            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            Processing...
          </span>
        ) : "Process Excel"}
      </Button>
      
      <DownloadButton 
        className="mt-2"
        downloadLinks={downloadLinks}
      />
    </div>
  );
}; 