import { Input } from "@/components/ui/forms";
import { Template } from "@/types/mapping";
import { FileSpreadsheet, FileText } from "lucide-react"

interface FileUploadersProps {
  selectedTemplate: Template | null;
  csvPreview: string[][];
  csvFile: File | null;
  excelFile: File | null;
  handleCsvChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  handleExcelChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
}

export const FileUploaders = ({
  selectedTemplate,
  csvPreview,
  csvFile,
  excelFile,
  handleCsvChange,
  handleExcelChange
}: FileUploadersProps) => {
  const allForcedInputs = selectedTemplate?.inputMappings?.every(i => i.source === "forced_input") || false;
  
  const showCsvUploader = !allForcedInputs && Boolean(selectedTemplate?.inputMappings?.length);

  return (
    <>
      <div className="mb-6">
        <label className="block mb-1 text-base font-semibold">Upload Excel File</label>
        <div className="border-2 border-dashed border-gray-300 rounded-xl p-4 text-center mb-3">
          <Input 
            type="file" 
            accept=".xlsx,.xls" 
            onChange={handleExcelChange} 
            className="hidden placeholder:text-gray-400" 
            id="excel-upload" 
          />
          <label 
            htmlFor="excel-upload" 
            className="cursor-pointer flex flex-col items-center"
          >
            <FileSpreadsheet className="h-8 w-8 mb-2 text-green-600" />
            <div className="text-sm font-medium text-green-600">Choose Excel File</div>
            <div className="text-xs text-gray-500 mt-1">.xlsx or .xls formats only</div>
          </label>
          {excelFile && (
            <div className="mt-2 text-sm text-green-700">
              Selected: {excelFile.name}
            </div>
          )}
        </div>
      </div>

      {showCsvUploader && (
        <div className="mb-6">
          <label className="block mb-1 text-base font-semibold">Upload CSV</label>
          <div className="border-2 border-dashed border-gray-300 rounded-xl p-4 text-center mb-3">
            <Input 
              type="file" 
              accept=".csv" 
              onChange={handleCsvChange} 
              className="hidden placeholder:text-gray-400" 
              id="csv-upload" 
            />
            <label 
              htmlFor="csv-upload" 
              className="cursor-pointer flex flex-col items-center"
            >
              <FileText className="h-8 w-8 mb-2 text-green-600" />
              <div className="text-sm font-medium text-green-600">Choose CSV File</div>
              <div className="text-xs text-gray-500 mt-1">CSV format only</div>
            </label>
            {csvFile && (
              <div className="mt-2 text-sm text-green-700">
                Selected: {csvFile.name}
              </div>
            )}
          </div>
          
          {csvPreview.length > 0 && (
            <div className="bg-gray-50 border rounded-lg p-3 text-xs">
              <div className="font-semibold mb-2 text-green-700">Preview:</div>
              <div className="overflow-x-auto">
                <table className="w-full border-collapse">
                  <tbody>
                    {csvPreview.map((row, i) => (
                      <tr key={i} className={`${i === 0 ? 'bg-green-50 font-medium' : 'bg-white'}`}>
                        {row.map((cell, j) => (
                          <td key={j} className="border border-gray-200 p-1.5 whitespace-nowrap">
                            {cell || <span className="text-gray-300">(empty)</span>}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      )}
    </>
  );
}; 