import ReactSelect, { MultiValue } from "react-select";

interface MappingTypeSelectProps {
  inputMappings: Array<{
    id: string;
    column?: string;
    cell: string;
  }>;
  selectedMappingIds: string[];
  setSelectedMappingIds: (ids: string[]) => void;
  setMappingTypeError: (error: string) => void;
}

export function MappingTypeSelect({
  inputMappings,
  selectedMappingIds,
  setSelectedMappingIds,
  setMappingTypeError
}: MappingTypeSelectProps) {
  return (
    <div>
      <label className="text-sm font-medium text-green-700">
        Mapping Type <span className="text-red-500">*</span>
      </label>
      <ReactSelect
        isMulti
        name="mappingTypes"
        options={inputMappings.map((mapping, index) => ({
          value: mapping.id,
          label: mapping.column || `Input ${index + 1} (${mapping.cell})`
        }))}
        className="basic-multi-select"
        classNamePrefix="select"
        value={selectedMappingIds.map(id => {
          const mapping = inputMappings.find(m => m.id === id);
          return mapping ? {
            value: mapping.id,
            label: mapping.column || `Input ${inputMappings.findIndex(m => m.id === mapping.id) + 1} (${mapping.cell})`
          } : null;
        }).filter(Boolean)}
        onChange={(newValue: MultiValue<{ value: string; label: string } | null>) => {
          const selectedOptions = newValue.filter(option => option !== null) as { value: string; label: string }[];
          const selectedIds = selectedOptions.map(option => option.value);
          setSelectedMappingIds(selectedIds);
          setMappingTypeError("");
        }}
        styles={{
          control: (base) => ({
            ...base,
            borderColor: '#22c55e',
            '&:hover': {
              borderColor: '#22c55e'
            },
            '&:focus-within': {
              borderColor: '#22c55e',
              boxShadow: '0 0 0 2px rgba(34, 197, 94, 0.2)'
            }
          })
        }}
      />
    </div>
  );
} 