import { useEffect, useState } from "react";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/forms";
import { getTemplates } from "@/services/templateApi";
import { toast } from "react-toastify";
import { Template } from "@/types/mapping";

interface TemplateSelectorProps {
  selectedId: string;
  setSelectedId: (id: string) => void;
  showDescription?: boolean;
}

export const TemplateSelector = ({ 
  selectedId, 
  setSelectedId,
  showDescription = true 
}: TemplateSelectorProps) => {
  const [templates, setTemplates] = useState<Template[]>([]);
  const [loading, setLoading] = useState(true);

  const isEmptyTemplatesError = (errorMessage: string): boolean => {
    const message = errorMessage.toLowerCase();
    const emptyTemplatePatterns = ["no template", "empty", "not found"];
    return emptyTemplatePatterns.some(pattern => message.includes(pattern));
  };

  useEffect(() => {
    const loadTemplates = async (): Promise<void> => {
      try {
        const fetchedTemplates = await getTemplates();
        setTemplates(fetchedTemplates);
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : "Failed to load templates";
        
        if (!isEmptyTemplatesError(errorMessage)) {
          toast.error(errorMessage);
        }
      } finally {
        setLoading(false);
      }
    };

    loadTemplates();
  }, []);

  if (loading) {
    return <div className="text-gray-500">Loading templates...</div>;
  }

  if (templates.length === 0) {
    return <div className="text-gray-500 text-sm">No templates available</div>;
  }

  return (
    <div className="mb-6">
      <label className="block mb-1 text-base">Select template</label>
      <Select value={selectedId} onValueChange={setSelectedId}>
        <SelectTrigger className="w-full rounded-xl bg-white border-gray-300 focus:ring-2 focus:ring-green-200">
          <SelectValue placeholder="Template" className="text-gray-500" />
        </SelectTrigger>
        <SelectContent className="rounded-lg bg-white min-w-[260px]">
          {templates.map((tpl) => (
            <SelectItem
              key={tpl.id}
              value={tpl.id}
              className="data-[highlighted]:bg-gray-100 data-[highlighted]:text-black cursor-pointer"
            >
              {showDescription ? (
                <div className="flex items-center justify-between w-full">
                  <span className="w-1/2 pr-2">{tpl.name}</span>
                  <span className="w-px h-5 bg-gray-300 mx-2" />
                  <span className="w-1/2 pl-2 text-xs text-gray-500">{tpl.description}</span>
                </div>
              ) : (
                tpl.name
              )}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}; 