import { useState, useCallback, useEffect } from "react";
import { v4 as uuidv4 } from "uuid";
import { InputMapping, OutputMapping, Template } from "@/types/mapping";
import { useNavigation } from "@/hooks/useNavigation";
import { createTemplate, getTemplateById, updateTemplate } from "@/services/templateApi";
import { toast } from "react-toastify";

export const useMappingForm = () => {
  const [templateName, setTemplateName] = useState<string>("");
  const [description, setDescription] = useState<string>("");
  const [inputMappings, setInputMappings] = useState<InputMapping[]>([]);
  const [outputMappings, setOutputMappings] = useState<OutputMapping[]>([]);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [originalTemplate, setOriginalTemplate] = useState<Template | null>(null);
  const [isTemplateModified, setIsTemplateModified] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [selectedMappingId, setSelectedMappingId] = useState<string>("");
  const [selectedMappingIds, setSelectedMappingIds] = useState<string[]>([]);
  const [mappingTypeError, setMappingTypeError] = useState<string>("");

  const { params } = useNavigation();

  // Load template from URL parameter
  useEffect(() => {
    const loadTemplateFromParams = async () => {
      const templateId = params.template;
      if (templateId) {
        try {
          const template = await getTemplateById(templateId);
          loadTemplate(template);
          setIsEditMode(true);
        } catch (error) {
          setError("form", `Failed to load template: ${(error as Error).message}`);
        }
      }
    };

    loadTemplateFromParams();
  }, [params.template]);

  const handleAddInput = () => {
    setInputMappings([
      ...inputMappings,
      { id: uuidv4(), column: "", cell: "", source: "input_file", forcedValue: "" },
    ]);
  };

  const handleAddOutput = () => {
    setOutputMappings([...outputMappings, { id: uuidv4(), name: "", cell: "" }]);
  };

  const handleRemoveInput = (id: string) => {
    setInputMappings(inputMappings.filter((m) => m.id !== id));
  };

  const handleRemoveOutput = (id: string) => {
    setOutputMappings(outputMappings.filter((m) => m.id !== id));
  };

  const handleInputChange = (index: number, field: string, value: string) => {
    setInputMappings((prev) =>
      prev.map((m, i) => (i === index ? { ...m, [field]: value } : m))
    );
    clearErrors(`input_${field}_${index}`);
  };

  const handleOutputChange = (index: number, field: string, value: string) => {
    setOutputMappings((prev) =>
      prev.map((m, i) => (i === index ? { ...m, [field]: value } : m))
    );
    clearErrors(`output_${field}_${index}`);
  };

  const validate = useCallback(() => {
    const newErrors: Record<string, string> = {};

    // Validate template name
    if (!templateName.trim()) {
      newErrors.templateName = "Template name is required";
    }

    // Validate input mappings
    if (inputMappings.length === 0) {
      newErrors.inputsRequired = "At least one input mapping is required";
    } else {
      inputMappings.forEach((mapping) => {
        if (!mapping.column.trim()) {
          newErrors[`input_name_${mapping.id}`] = "Column name is required";
        }
        if (!mapping.cell) {
          newErrors[`input_cell_${mapping.id}`] = "Cell must be selected";
        }
        if (mapping.source === "forced_input" && !mapping.forcedValue?.trim()) {
          newErrors[`input_forcedValue_${mapping.id}`] = "Forced value is required";
        }
      });
    }

    // Validate output mappings
    if (outputMappings.length === 0) {
      newErrors.outputsRequired = "At least one output mapping is required";
    } else {
      outputMappings.forEach((mapping) => {
        if (!mapping.name.trim()) {
          newErrors[`output_name_${mapping.id}`] = "Name is required";
        }
        if (!mapping.cell) {
          newErrors[`output_cell_${mapping.id}`] = "Cell must be selected";
        }
      });
    }

    // Validate mapping type selection
    if (inputMappings.length > 0 && selectedMappingIds.length === 0) {
      newErrors.mappingType = "Please select at least one mapping type";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }, [templateName, inputMappings, outputMappings, selectedMappingIds]);

  const loadTemplate = (template: Template) => {
    setTemplateName(template.name);
    setDescription(template.description || "");
    setInputMappings(template.inputMappings);
    setOutputMappings(template.outputMappings);
    setOriginalTemplate(template);
    setIsTemplateModified(false);
    setErrors({});
  };

  const handleSaveTemplate = async () => {
    setIsSubmitted(true);
    if (!validate()) {
      return;
    }

    setIsSubmitting(true);

    try {
      const templateData = {
        name: templateName,
        description,
        inputMappings,
        outputMappings,
        identityMappings: selectedMappingIds.map(id => {
          const mapping = inputMappings.find(m => m.id === id);
          return {
            id: uuidv4(),
            templateId: "0", // Will be set by server
            name: mapping?.column || ""
          };
        }),
        selectedMappingIds
      };

      if (isEditMode && originalTemplate) {
        // Update existing template
        await updateTemplate(originalTemplate.id, {
          name: templateName,
          description,
          input_mappings: inputMappings.map(mapping => ({
            name: mapping.column,
            source: mapping.source || "input_file",
            cell: mapping.cell,
            forced_value: mapping.forcedValue
          })),
          output_mappings: outputMappings.map(mapping => ({
            field: mapping.name,
            cell: mapping.cell
          })),
          identity_mappings: selectedMappingIds.map(id => {
            const mapping = inputMappings.find(m => m.id === id);
            return {
              id: uuidv4(),
              templateId: "0", // Will be set by server
              name: mapping?.column || ""
            };
          })
        });
        toast.success("Template updated successfully");
      } else {
        // Create new template
        await createTemplate(templateData);
        toast.success("Template created successfully");
      }
      
      // Reset form
      setTemplateName("");
      setDescription("");
      setInputMappings([]);
      setOutputMappings([]);
      setSelectedMappingId("");
      setSelectedMappingIds([]);
      clearErrors();
    } catch (error) {
      setError("form", (error as Error).message || "Failed to save template");
    } finally {
      setIsSubmitting(false);
    }
  };

  useEffect(() => {
    if (isSubmitted) {
      validate();
    }
  }, [isSubmitted, validate]);

  useEffect(() => {
    if (!originalTemplate) return;

    const isModified = 
      templateName !== originalTemplate.name ||
      description !== originalTemplate.description ||
      JSON.stringify(inputMappings) !== JSON.stringify(originalTemplate.inputMappings) ||
      JSON.stringify(outputMappings) !== JSON.stringify(originalTemplate.outputMappings);

    setIsTemplateModified(isModified);
  }, [templateName, description, inputMappings, outputMappings, originalTemplate]);

  const setError = (field: string, message: string) => {
    setErrors(prev => ({ ...prev, [field]: message }));
  };

  const clearError = (field: string) => {
    setErrors(prev => {
      const newErrors = { ...prev };
      delete newErrors[field];
      return newErrors;
    });
  };

  const clearErrors = (key?: string) => {
    if (key) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[key];
        return newErrors;
      });
    } else {
      setErrors({});
    }
  };

  const addInputMapping = () => {
    const newMapping: InputMapping = {
      id: uuidv4(),
      column: "",
      cell: "",
      source: "input_file",
      forcedValue: null
    };
    setInputMappings(prev => [newMapping, ...prev]);
  };

  const removeInputMapping = (id: string) => {
    setInputMappings(prev => prev.filter(mapping => mapping.id !== id));
  };

  const updateInputMapping = (id: string, field: string, value: string) => {
    setInputMappings(prev => 
      prev.map(mapping => 
        mapping.id === id 
          ? { ...mapping, [field]: value }
          : mapping
      )
    );
    clearErrors(`input_${field}_${id}`);
  };

  const addOutputMapping = () => {
    const newMapping: OutputMapping = {
      id: uuidv4(),
      name: "",
      cell: ""
    };
    setOutputMappings(prev => [newMapping, ...prev]);
  };

  const removeOutputMapping = (id: string) => {
    setOutputMappings(prev => prev.filter(mapping => mapping.id !== id));
  };

  const updateOutputMapping = (id: string, field: string, value: string) => {
    setOutputMappings(prev => 
      prev.map(mapping => 
        mapping.id === id 
          ? { ...mapping, [field]: value }
          : mapping
      )
    );
    clearErrors(`output_${field}_${id}`);
  };

  const resetForm = () => {
    setTemplateName("");
    setDescription("");
    setInputMappings([]);
    setOutputMappings([]);
    setSelectedMappingIds([]);
    setMappingTypeError("");
    clearErrors();
  };

  return {
    templateName,
    setTemplateName,
    description,
    setDescription,
    inputMappings,
    outputMappings,
    errors,
    setError,
    clearError,
    handleAddInput,
    handleAddOutput,
    handleRemoveInput,
    handleRemoveOutput,
    handleInputChange,
    handleOutputChange,
    handleSaveTemplate,
    loadTemplate,
    isTemplateModified,
    isEditMode,
    isSubmitting,
    selectedMappingId,
    setSelectedMappingId,
    selectedMappingIds,
    setSelectedMappingIds,
    mappingTypeError,
    setMappingTypeError,
    addInputMapping,
    removeInputMapping,
    updateInputMapping,
    addOutputMapping,
    removeOutputMapping,
    updateOutputMapping,
    originalTemplate,
    resetForm
  };
}; 