import { useExcel } from "@/hooks/useExcel";
import { toast } from "react-toastify";

export const useExcelTemplate = () => {
  const { getSelectedCell } = useExcel();

  const checkForFormula = async (cell: string): Promise<boolean> => {
    try {
      const result = await Excel.run(async (context) => {
        const range = context.workbook.worksheets
          .getActiveWorksheet()
          .getRange(cell);
        range.load("formulas");
        await context.sync();

        const formula = range.formulas[0][0];
        return (
          formula !== null &&
          formula !== "" &&
          formula.toString().startsWith("=")
        );
      });
      return result;
    } catch {
      return false;
    }
  };

  const handleCellSelect = async (
    isInput: boolean = false
  ): Promise<{ cell: string; hasFormula: boolean } | null> => {
    try {
      const cell = await getSelectedCell();
      if (!cell) return null;

      const hasFormula = await checkForFormula(cell);

      if (hasFormula && isInput) {
        toast.error("❌ Cannot use a formula cell as input", {
          position: "top-center",
          autoClose: 3000,
        });
      }

      return { cell, hasFormula };
    } catch {
      toast.error("Failed to select cell");
      return null;
    }
  };

  const handleFileUpload = async (file: File): Promise<boolean> => {
    if (!file) return false;

    try {
      await Excel.run(async (context) => {
        const workbook = context.workbook;
        const worksheet = workbook.worksheets.add();
        worksheet.name = file.name.split(".")[0];

        worksheet.activate();
        await context.sync();
      });

      toast.success("Template file loaded successfully!");
      return true;
    } catch {
      toast.error("Failed to process template file");
      return false;
    }
  };

  return {
    handleCellSelect,
    handleFileUpload,
  };
};
