import { useState, useEffect, useRef } from "react";
import { Button } from "@/components/ui/buttons";
import { ChevronDown, ChevronUp, X, Target } from "lucide-react";

interface CellPickerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (cell: string, mappingId: string) => void;
  initialCell?: string;
  mappingId: string;
}

export function CellPickerModal({
  isOpen,
  onClose,
  onSelect,
  initialCell = "",
  mappingId,
}: CellPickerModalProps) {
  const [cellAddress, setCellAddress] = useState(initialCell);
  const [isHelpExpanded, setIsHelpExpanded] = useState(false);
  const [isPickingMode, setIsPickingMode] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const [isReady, setIsReady] = useState(false);
  
  const refs = {
    lastCell: useRef<string>(""),
    userClicked: useRef<boolean>(false),
    startTime: useRef<number>(0),
    savedValue: useRef<string | null>(null),
    isSaving: useRef<boolean>(false)
  };
  
  useEffect(() => {
    if (isOpen && !isVisible) {
      setIsVisible(true);
      setTimeout(() => setIsReady(true), 10);
      refs.isSaving.current = false;
      refs.savedValue.current = null;
      setIsPickingMode(true);
    } else if (!isOpen && isVisible) {
      setIsReady(false);
      setTimeout(() => setIsVisible(false), 300);
    }
  }, [isOpen, isVisible, refs.isSaving, refs.savedValue]);

  useEffect(() => {
    if (isVisible && initialCell) {
      setCellAddress(initialCell);
      setIsPickingMode(false);
    }
  }, [isVisible, initialCell]);

  useEffect(() => {
    if (!isVisible || !isPickingMode) return;
    
    refs.userClicked.current = false;
    refs.startTime.current = Date.now();
    
    const getCurrentCell = async () => {
      try {
        await Excel.run(async (context) => {
          const range = context.workbook.getSelectedRange();
          range.load("address");
          await context.sync();
          if (range.address) refs.lastCell.current = range.address;
        });
      } catch (error) {
        console.error("Error getting initial cell:", error);
      }
    };
    
    getCurrentCell();
    
    let intervalId: number | null = null;
    let isActive = true;
    
    const checkForClicks = () => {
      if (!isActive || !isPickingMode) {
        if (intervalId) clearInterval(intervalId);
        return;
      }
      
      if (Date.now() - refs.startTime.current < 500) return;
      
      Excel.run(async (context) => {
        const range = context.workbook.getSelectedRange();
        range.load("address");
        await context.sync();
        
        if (!range.address || !isActive) return;
        
        if (range.address !== refs.lastCell.current) {
          refs.userClicked.current = true;
          setCellAddress(range.address);
          setIsPickingMode(false);
          if (intervalId) clearInterval(intervalId);
        }
        
        refs.lastCell.current = range.address;
      }).catch(error => console.error("Error checking for cell changes:", error));
    };
    
    intervalId = window.setInterval(checkForClicks, 300);
    
    return () => {
      isActive = false;
      if (intervalId) clearInterval(intervalId);
    };
  }, [isVisible, isPickingMode, refs.lastCell, refs.startTime, refs.userClicked]);

  const closeDialog = (callback?: () => void) => {
    setIsReady(false);
    setTimeout(() => callback?.(), 300);
  };

  const handleSave = () => {
    if (!cellAddress || refs.isSaving.current) return;
    
    refs.isSaving.current = true;
    refs.savedValue.current = cellAddress;
    
    closeDialog(() => {
      if (refs.savedValue.current) {
        onSelect(refs.savedValue.current, mappingId);
        onClose();
        refs.isSaving.current = false;
        refs.savedValue.current = null;
      }
    });
  };

  const handleCancel = () => closeDialog(onClose);
  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) closeDialog(onClose);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isVisible) closeDialog(onClose);
    };
    
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isVisible, onClose]);

  if (!isVisible) return null;
  
  return (
    <div 
      className={`fixed inset-0 flex items-center justify-center z-50 bg-black/50 transition-opacity duration-300 ${
        isReady ? 'opacity-100' : 'opacity-0'
      }`}
      onClick={handleBackdropClick}
      aria-modal="true"
      role="dialog"
    >
      <div 
        className={`max-w-md w-full bg-white border-green-600 rounded-lg shadow-lg transform transition-transform duration-300 ${
          isReady ? 'translate-y-0' : 'translate-y-8'
        }`}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="border-b border-gray-200 pb-3 px-6 pt-4">
          <div className="text-lg font-semibold text-green-700">Cell Reference</div>
        </div>

        <div className="py-4 px-6 space-y-4">
          {!isPickingMode && !cellAddress && (
            <div className="p-3 bg-blue-50 border border-blue-200 rounded-md text-blue-700 text-sm space-y-2">
              <p>Click the <strong>"Pick Cell"</strong> button to select a cell from Excel spreadsheet</p>
            </div>
          )}
          
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-700">Reference</label>
            <div className="flex items-center gap-2">
              <div className="relative flex-1">
                <input
                  type="text"
                  value={cellAddress}
                  onChange={(e) => setCellAddress(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md bg-gray-50 text-sm pr-8"
                  placeholder="Enter cell reference (e.g. A1)"
                />
                {cellAddress && (
                  <button
                    type="button"
                    onClick={() => setCellAddress("")}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  >
                    <X />
                  </button>
                )}
              </div>
              <Button 
                type="button" 
                onClick={() => {
                  setIsPickingMode(!isPickingMode);
                  refs.userClicked.current = false;
                  refs.startTime.current = Date.now();
                }}
                variant="default"
                className={`flex items-center gap-1 px-3 ${
                  isPickingMode 
                  ? "bg-amber-500 hover:bg-amber-600" 
                  : "bg-green-600 hover:bg-green-700"
                } text-white`}
              >
                {isPickingMode ? (
                  <>
                    <X size={16} />
                    <span>Cancel Selection</span>
                  </>
                ) : (
                  <>
                    <Target size={16} />
                    <span>Pick Cell</span>
                  </>
                )}
              </Button>
            </div>
            
            {isPickingMode && (
              <div className="mt-2 p-3 bg-amber-50 border border-amber-200 rounded-md text-amber-700 text-sm space-y-2">
                <p className="font-medium">Selection mode activated:</p>
                <ol className="list-decimal pl-5 space-y-1">
                  <li>Go to Excel spreadsheet</li>
                  <li>Click on the desired cell</li>
                  <li>The cell will be automatically selected</li>
                </ol>
              </div>
            )}
          </div>

          <div className="space-y-2">
            <button
              onClick={() => setIsHelpExpanded(!isHelpExpanded)}
              className="flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900"
            >
              {isHelpExpanded ? (
                <>
                  <ChevronUp size={16} />
                  Hide Help
                </>
              ) : (
                <>
                  <ChevronDown size={16} />
                  Show Help
                </>
              )}
            </button>

            {isHelpExpanded && (
              <div className="p-3 bg-gray-50 rounded-md space-y-2 text-sm text-gray-600">
                <p>You can either:</p>
                <ul className="list-disc pl-5">
                  <li>Type a cell reference manually (e.g. A1)</li>
                  <li>
                    Click "Pick Cell" and then select a cell in Excel:
                    <ul className="list-disc pl-4 mt-1 text-xs">
                      <li>When in pick mode, Excel will highlight cells as you click on them</li>
                      <li>Simply click on any cell to select it</li>
                    </ul>
                  </li>
                </ul>
                <p>Click Save to confirm your selection.</p>
              </div>
            )}
          </div>
        </div>

        <div className="border-t border-gray-200 pt-3 pb-4 px-6 flex justify-end gap-2">
          <Button
            variant="outline"
            onClick={handleCancel}
            className="text-sm border-gray-300 hover:bg-gray-50"
          >
            Cancel
          </Button>
          <Button
            variant="default"
            onClick={handleSave}
            className="text-sm bg-green-600 hover:bg-green-700 text-white shadow-sm"
            disabled={!cellAddress || isPickingMode}
          >
            Save
          </Button>
        </div>
      </div>
    </div>
  );
} 