import { useNavigation } from '@/hooks/useNavigation'
import { RunModal } from '@/pages/RunModal'
import { CreateTemplatePage } from '@/pages/CreateTemplatePage'
import { UseTemplate } from '@/pages/UseTemplate'
import { ViewPage } from '@/pages/ViewPage'
import { Page } from '@/constants/navigation'

export function Navigation() {
  const { currentPage } = useNavigation()

  return (
    <main className="flex flex-col p-2">
      {currentPage === Page.BATCH && <RunModal />}
      {currentPage === Page.TEMPLATE && <CreateTemplatePage />}
      {currentPage === Page.RUN_TEMPLATE && <UseTemplate />}
      {currentPage === Page.TEMPLATES_LIST && <ViewPage />}
    </main>
  )
} 