import { Label } from "@/components/ui/forms";
import { Input, Textarea } from "@/components/ui/forms";

interface TemplateHeaderProps {
  templateName: string;
  setTemplateName: (value: string) => void;
  description: string;
  setDescription: (value: string) => void;
  errors: {
    templateName?: string;
  };
}

export function TemplateHeader({
  templateName,
  setTemplateName,
  description,
  setDescription,
  errors,
}: TemplateHeaderProps) {
  return (
    <>
      <div className="space-y-2">
        <Label htmlFor="templateName">Template Name *</Label>
        <Input
          id="templateName"
          className="rounded-xl bg-white focus:ring-2 focus:ring-green-200 border-green-600"
          value={templateName}
          onChange={(e) => setTemplateName(e.target.value)}
        />
        {errors.templateName && (
          <div className="text-red-500/70 text-xs mt-1 font-medium">
            {errors.templateName}
          </div>
        )}
      </div>

      <div className="space-y-2">
        <Label htmlFor="description">Description</Label>
        <Textarea
          id="description"
          className="rounded-xl bg-white focus:ring-2 focus:ring-green-200 border-green-600"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
      </div>
    </>
  );
} 