import React from "react";
import { ScrollArea } from "@/components/ui/layout/scroll-area";
import { GenericTable } from "@/components/ui/layout/table";
import { EditTemplateModal } from "./EditTemplateModal";
import { TemplateRow } from "./TemplateRow";
import { TEMPLATE_TABLE_COLUMNS } from "./tableColumns";
import { useTemplates } from "@/hooks/useTemplates";
import { Template } from "@/types/mapping";

export default function TemplatesList() {
  const { templates, isLoading, error, handleDeleteTemplate, refreshTemplates } = useTemplates();
  const [editModalOpen, setEditModalOpen] = React.useState(false);
  const [selectedTemplateId, setSelectedTemplateId] = React.useState<string | null>(null);

  const handleEdit = React.useCallback((templateId: string) => {
    setSelectedTemplateId(templateId);
    setEditModalOpen(true);
  }, []);

  const handleCloseModal = React.useCallback(() => {
    setEditModalOpen(false);
    setSelectedTemplateId(null);
  }, []);

  const renderTemplateRow = React.useCallback((template: Template) => (
    <TemplateRow
      template={template}
      onEdit={handleEdit}
      onDelete={handleDeleteTemplate}
    />
  ), [handleEdit, handleDeleteTemplate]);

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-32">
        Loading templates...
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-red-500 text-center">
        Error: {error}
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold">Saved Templates</h2>
        <div className="text-sm text-gray-500">
          {templates.length} template{templates.length !== 1 ? 's' : ''}
        </div>
      </div>

      <ScrollArea className="flex-1">
        <GenericTable
          columns={TEMPLATE_TABLE_COLUMNS}
          data={[...templates].reverse()}
          renderRow={renderTemplateRow}
          maxHeight="calc(100vh - 250px)"
          className="mb-6"
        />
      </ScrollArea>

      <EditTemplateModal
        isOpen={editModalOpen}
        onClose={handleCloseModal}
        templateId={selectedTemplateId}
        onSuccess={refreshTemplates}
      />
    </div>
  );
} 