import React from "react";
import { useTemplatesStore } from "@/store/templates";
import { getTemplates, deleteTemplate } from "@/services/templateApi";
import { toast } from "react-toastify";

export function useTemplates() {
  const { templates, removeTemplate, loadTemplates } = useTemplatesStore();
  const [isLoading, setIsLoading] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  const fetchTemplates = React.useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);
      const fetchedTemplates = await getTemplates();
      loadTemplates(fetchedTemplates);
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setIsLoading(false);
    }
  }, [loadTemplates]);

  const handleDeleteTemplate = React.useCallback(async (templateId: string) => {
    try {
      await deleteTemplate(templateId);
      removeTemplate(templateId);
      toast.success("Template deleted successfully");
    } catch (err) {
      toast.error((err as Error).message || "Failed to delete template");
    }
  }, [removeTemplate]);

  const refreshTemplates = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const fetchedTemplates = await getTemplates();
      loadTemplates(fetchedTemplates);
    } catch {
      toast.error("Failed to refresh templates");
    } finally {
      setIsLoading(false);
    }
  }, [loadTemplates]);

  React.useEffect(() => {
    fetchTemplates();
  }, [fetchTemplates]);

  return {
    templates,
    isLoading,
    error,
    handleDeleteTemplate,
    refreshTemplates
  };
} 